   S("الحكم وأدلته", ["الوجوب: «فاحكم بين الناس بالحق» (ص 26) ؛ تولاه النبي ﷺ وبعث عليا ومعاذا قاضيين ؛ إجماع المسلمين.", "ينصب القاضي الإمام العدل أو نائبه، وإلا فجماعة المسلمين."]),
   S("الأحكام الخمسة في تولي القضاء", table=[["الحكم", "لمن"], ["واجب (كفاية/عين)", "يتعين على من يصلح له إن لم يوجد غيره"], ["مندوب", "لخامل الذكر، ولمن هو أنفع للمسلمين"], ["جائز", "لمن احتاجه لمعاشه مع توفر الشروط"], ["مكروه", "لطالب الجاه، ولمن غيره أصلح منه"], ["حرام", "على الجاهل والفاسق والمرتشي والظالم والعاجز"]]),
